const e="Les Temps Innommables désignent la période la plus ancienne de l'existence d'Asun. Elle précède toute histoire fiable, toute civilisation...",n=["Public","histoire"],t=[2,3,4],s=[{title:"Présentation",type:"text",content:`Les Temps Innommables désignent la période la plus ancienne de l'existence d'Asun.
Elle précède toute histoire fiable, toute civilisation connue et tout récit pouvant être vérifié.

C'est durant cette période que se situent les événements les plus anciens connus :
- l'existence de l'Innommé ;
- l'apparition des Forces ;
- l'apparition d'Asun ;
- l'éveil des dieux ;
- les premières transformations du monde.

Aucun calendrier mortel ne permet de mesurer cette époque.`},{title:"TEST",type:"banner",subtitle:"Ceci est un test",content:"Les Temps Innommables désignent la période la plus ancienne de l'existence d'Asun."},{type:"banner",subtitle:"Ceci est un test",content:"Les Temps Innommables désignent la période la plus ancienne de l'existence d'Asun."},{title:"Secrets",type:"dm-banner",content:"Les Temps Innommables désignent la période la plus ancienne de l'existence d'Asun."}],i={citation:e,tags:n,link_articles:t,sections:s};export{e as citation,i as default,t as link_articles,s as sections,n as tags};
